//! A tiny Stremio addon for tests and demos. Serves manifest/catalog/meta/stream/subtitles
//! for one generated test-pattern video. No third-party content is bundled: the video is
//! generated by `scripts/make-fixtures.sh` (ffmpeg testsrc) and served from `media_dir`.

use std::io::{BufRead, BufReader, Read, Seek, SeekFrom, Write};
use std::net::{TcpListener, TcpStream};
use std::path::PathBuf;
use std::sync::Arc;

pub const META_ID: &str = "tt-test1";
pub const VIDEO_FILE: &str = "test-pattern.mp4";

#[derive(Clone, Default)]
pub struct Config {
    /// Directory containing `test-pattern.mp4`, served under `/media/`.
    pub media_dir: Option<PathBuf>,
    /// (info hash, peer address) of a local seeder for the same video.
    pub torrent: Option<(String, String)>,
}

/// Serve forever on `listener`, one thread per connection.
pub fn serve(listener: TcpListener, cfg: Config) {
    let cfg = Arc::new(cfg);
    for conn in listener.incoming().flatten() {
        let cfg = cfg.clone();
        std::thread::spawn(move || {
            let _ = handle(conn, &cfg);
        });
    }
}

/// Bind 127.0.0.1:0, serve in a background thread, return the base URL (`http://127.0.0.1:port`).
pub fn spawn(cfg: Config) -> std::io::Result<String> {
    let l = TcpListener::bind("127.0.0.1:0")?;
    let base = format!("http://{}", l.local_addr()?);
    std::thread::spawn(move || serve(l, cfg));
    Ok(base)
}

fn manifest() -> serde_json::Value {
    serde_json::json!({
        "id": "org.example.testaddon",
        "version": "1.0.0",
        "name": "Test Addon",
        "description": "Local test addon serving a generated test pattern.",
        "resources": ["catalog", "meta", "stream", "subtitles"],
        "types": ["movie"],
        "idPrefixes": ["tt-test"],
        "catalogs": [{"type": "movie", "id": "test-movies", "name": "Test Movies"}]
    })
}

fn meta_preview() -> serde_json::Value {
    serde_json::json!({
        "id": META_ID, "type": "movie", "name": "Test Pattern",
        "description": "Generated SMPTE-style test pattern with a 440 Hz tone (ffmpeg testsrc)."
    })
}

fn route(path: &str, host: &str, cfg: &Config) -> Option<(&'static str, Vec<u8>)> {
    let json = |v: serde_json::Value| Some(("application/json", v.to_string().into_bytes()));
    // Stremio may insert extra args as a path segment: /stream/movie/<id>/<extra>.json
    let p = path.split('?').next().unwrap_or("");
    match p {
        "/manifest.json" => json(manifest()),
        "/catalog/movie/test-movies.json" => json(serde_json::json!({ "metas": [meta_preview()] })),
        _ if p.starts_with(&format!("/meta/movie/{META_ID}")) => {
            let mut m = meta_preview();
            m["releaseInfo"] = "2026".into();
            json(serde_json::json!({ "meta": m }))
        }
        _ if p.starts_with(&format!("/stream/movie/{META_ID}")) => {
            let mut streams = vec![serde_json::json!({
                "name": "Test Addon", "title": "Test pattern (HTTP)",
                "url": format!("http://{host}/media/{VIDEO_FILE}")
            })];
            if let Some((hash, peer)) = &cfg.torrent {
                streams.push(serde_json::json!({
                    "name": "Test Addon", "title": "Test pattern (torrent)",
                    "infoHash": hash, "fileIdx": 0, "sources": [format!("peer:{peer}")]
                }));
            }
            json(serde_json::json!({ "streams": streams }))
        }
        _ if p.starts_with(&format!("/subtitles/movie/{META_ID}")) => json(serde_json::json!({
            "subtitles": [{"id": "test-en", "lang": "eng", "url": format!("http://{host}/subs/test-en.vtt")}]
        })),
        "/subs/test-en.vtt" => Some((
            "text/vtt",
            b"WEBVTT\n\n00:00:00.000 --> 00:00:30.000\nTest subtitle: hello from the test addon\n".to_vec(),
        )),
        // Deliberately broken addon, for malformed-response tests.
        "/malformed/manifest.json" => Some(("application/json", b"{\"id\": 42, \"name\": [".to_vec())),
        _ => None,
    }
}

fn handle(mut conn: TcpStream, cfg: &Config) -> std::io::Result<()> {
    let mut reader = BufReader::new(conn.try_clone()?);
    let mut request_line = String::new();
    reader.read_line(&mut request_line)?;
    let (mut host, mut range) = (String::from("127.0.0.1"), None::<u64>);
    loop {
        let mut line = String::new();
        if reader.read_line(&mut line)? == 0 || line.trim().is_empty() {
            break;
        }
        let (k, v) = line.split_once(':').unwrap_or(("", ""));
        match k.trim().to_ascii_lowercase().as_str() {
            "host" => host = v.trim().to_string(),
            "range" => range = v.trim().strip_prefix("bytes=").and_then(|r| r.split('-').next()?.parse().ok()),
            _ => {}
        }
    }
    let mut parts = request_line.split_whitespace();
    let (method, path) = (parts.next().unwrap_or(""), parts.next().unwrap_or(""));
    if method != "GET" && method != "HEAD" {
        return write!(conn, "HTTP/1.1 405 Method Not Allowed\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
    }
    let cors = "Access-Control-Allow-Origin: *\r\nConnection: close\r\n";
    if path == format!("/media/{VIDEO_FILE}") {
        if let Some(Ok(mut f)) = cfg.media_dir.as_ref().map(|d| std::fs::File::open(d.join(VIDEO_FILE))) {
            let len = f.metadata()?.len();
            let start = range.unwrap_or(0).min(len);
            f.seek(SeekFrom::Start(start))?;
            let status = if range.is_some() { "206 Partial Content" } else { "200 OK" };
            write!(conn, "HTTP/1.1 {status}\r\nContent-Type: video/mp4\r\nAccept-Ranges: bytes\r\nContent-Length: {}\r\n", len - start)?;
            if range.is_some() {
                write!(conn, "Content-Range: bytes {start}-{}/{len}\r\n", len.saturating_sub(1))?;
            }
            write!(conn, "{cors}\r\n")?;
            if method == "GET" {
                std::io::copy(&mut f.take(len - start), &mut conn)?;
            }
            return Ok(());
        }
    }
    match route(path, &host, cfg) {
        Some((ctype, body)) => {
            write!(conn, "HTTP/1.1 200 OK\r\nContent-Type: {ctype}\r\nContent-Length: {}\r\n{cors}\r\n", body.len())?;
            if method == "GET" {
                conn.write_all(&body)?;
            }
            Ok(())
        }
        None => write!(conn, "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n{cors}\r\n"),
    }
}
